"""Shared presentation for vocabulary concepts and browse directories."""
from html import escape

CSS = '''
@font-face{font-family:Cormorant;src:url('/fonts/cormorant-garamond-regular.ttf') format('truetype');font-display:swap}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}*{box-sizing:border-box}body{margin:0;background:#f6f7f9;color:#182027;font:16px/1.6 Arial,Helvetica,sans-serif}a{color:#1664a3;text-decoration:none}a:hover{text-decoration:underline}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid #1664a3;outline-offset:4px}.site-header{padding:24px 5%;border-bottom:1px solid #d5dce3}.header-inner{display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap;max-width:1400px;margin:auto}.brand-link{display:flex;align-items:center;gap:12px;color:#182027;font:32px Cormorant,Georgia,serif}.brand-link,.brand-link:hover,.brand-link:focus,.brand-link:focus-visible,.brand-link:active,.brand-link:visited{text-decoration:none}.brand-mark{width:38px;height:38px}.main-nav{display:flex;gap:26px;font-size:14px;flex-wrap:wrap}.page-shell{max-width:1040px;margin:auto;padding:30px 6% 48px}.breadcrumb{font-size:13px;display:flex;gap:12px;flex-wrap:wrap;color:#65717d;margin-bottom:36px}.vocabulary-badge{display:block;text-transform:uppercase;font-size:11px;letter-spacing:.15em;color:#65717d;margin-bottom:12px}h1{font:400 clamp(38px,5vw,58px)/1.07 Cormorant,Georgia,serif;letter-spacing:-.02em;margin:0 0 20px;overflow-wrap: anywhere}h2{font:400 30px/1.2 Cormorant,Georgia,serif;margin:0 0 14px}.definition{max-width:740px;font-size:19px;color:#65717d;margin-bottom:22px}.definition h2{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.definition p{margin:0 0 22px}.search-topic{display:inline-block;background:#1664a3;color:white;padding:12px 18px;border-radius:3px;font-size:14px;margin-bottom:8px}.term-section:not(.definition){margin-top:34px}.concept-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:36px;list-style: none;padding:0;margin:0;border-top:1px solid #d5dce3}.concept-grid li{min-width:0;border-bottom:1px solid #d5dce3}.concept-link{display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:56px;padding:13px 4px;font-size:15px;overflow-wrap: anywhere}.concept-link:hover{background:#edf1f5;text-decoration:none}.concept-arrow{color:#65717d;flex-shrink:0}.concept-link-static{color:#65717d}.empty-relations{color:#65717d;margin:30px 0}.technical-details{margin-top:36px;border-block:1px solid #d5dce3;padding:16px 0}.technical-details summary{cursor:pointer;color:#65717d;font-size:14px}.uri-block{margin-top:18px}.uri-heading{display:flex;align-items:center;gap:20px;margin-bottom:10px;font-size:13px;color:#65717d}#canonical-uri{font-size:12px;overflow-wrap: anywhere}.copy-uri-button{border:1px solid #d5dce3;background:transparent;color:#1664a3;padding:8px 12px;border-radius:3px;cursor:pointer}.copy-uri-status{font-size:12px;color:#65717d}.source-details{margin:20px 0}.source-details div{margin:15px 0}.source-details dt{font-weight:bold}.source-details dd{margin:0;overflow-wrap: anywhere}.page-footer{border-top:1px solid #d5dce3;padding:22px 5%;display:flex;gap:20px;justify-content:space-between;flex-wrap:wrap;color:#65717d;font-size:13px}.browse-sections{display:grid;grid-template-columns:1fr 1fr;gap:38px}.browse-intro{color:#65717d;max-width:700px}.browse-sections .concept-grid{grid-template-columns:1fr}.browse-links,.pagination{display:flex;gap:22px;flex-wrap:wrap;margin:24px 0}.pagination [aria-current]{font-weight:bold}.small{font-size:13px;color:#65717d}
@media (max-width: 600px){.concept-grid,.browse-sections{grid-template-columns:1fr}.main-nav{gap:20px}.brand-link{font-size:27px}.definition{font-size:17px}.page-shell{padding:24px 6% 36px}.breadcrumb{margin-bottom:28px}}
'''
HEADER = '''<header class="site-header"><div class="header-inner" data-nosnippet><a class="brand-link" href="/" aria-label="Universal Evidence home"><img class="brand-mark" src="/assets/ue-mark-transparent.svg" alt=""><span class="brand-name">Universal Evidence</span></a><nav class="main-nav" aria-label="Main navigation"><a href="/browse">Browse</a><a href="/journal/childhood-stunting.html">Journal</a><a href="/about.html">About</a><a href="/explore.html">Search</a></nav></div></header>'''
FOOTER = '''<div data-nosnippet style="display:contents"><footer class="page-footer"><span>Universal Evidence · Know what’s been done. Decide what’s next.</span><a href="/open-standards.html">Open standards</a></footer></div>'''

def page(title, description, canonical, content, script=""):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(description, quote=True)}"><link rel="canonical" href="{escape(canonical, quote=True)}"><link rel="icon" type="image/svg+xml" href="/assets/ue-mark-transparent.svg"><style>{CSS}</style><script defer src="https://cloud.umami.is/script.js" data-website-id="c1903a71-2894-474a-ab38-5d28a8a75884"></script></head><body>{HEADER}<main class="page-shell">{content}</main>{FOOTER}{script}</body></html>'''
